// Expressive Iteration
// status: ready
// Look at the top three cards of your library. Put one of them into your hand, put one of them on the bottom of your library, and exile one of them. You may play the exiled card this turn.
#[allow(unused_imports)] use cantrip_api::*;
fn ability_0(g: &mut dyn Game, item: &StackItem) -> Result<(), Suspend> { let asker = &Asker::new(item.object, item.controller);
let player_0 = { let q: &dyn Query = g; Some(asker.controller).expect("a reference that always names a player") }; let depth_0 = { let q: &dyn Query = g; (3i64).max(0) as usize }; let looked_0 = cantrip_mechanics::top_of_library(g, player_0, depth_0); let mut moved_0: Vec<ObjectId> = Vec::new(); if !looked_0.is_empty() { let hand = looked_0.len().min(1) as u8; let bottom = (looked_0.len() - hand as usize).min(1) as u8; let exile = (looked_0.len() - hand as usize - bottom as usize).min(1) as u8; let ask = RequestKind::DistributeCards { source: asker.source, cards: looked_0.clone(), destinations: vec![Destination { kind: DestinationKind::Hand, min: hand, max: hand, eligible: looked_0.clone() }, Destination { kind: DestinationKind::LibraryBottom, min: bottom, max: bottom, eligible: looked_0.clone() }, Destination { kind: DestinationKind::Exile, min: exile, max: exile, eligible: looked_0.clone() }], may_shuffle: false }; if let Answer::Placements { placements, .. } = g.ask(player_0, ask)? { g.return_to_hand(&placements[0]); g.arrange_library(player_0, &[], &placements[1]); moved_0 = g.exile_all(&placements[2]); } }
g.end_sentence();
let cards_1_0 = { let q: &dyn Query = g; (moved_0.clone()).get(0 as usize).copied().into_iter().collect::<Vec<ObjectId>>() }; let players_1_0 = { let q: &dyn Query = g; Some(asker.controller).into_iter().collect::<Vec<PlayerId>>() }; cantrip_api::instruction(g, |g| { for &card in &cards_1_0 { if g.obj(card).zone.is(ZoneKind::Exile) { for &player in &players_1_0 { g.allow_play(card, player, PlayGrant { lands: true, expiry: Expiry::EndOfTurn, ..PlayGrant::CAST }); } } } });
g.end_sentence();
 Ok(()) }

